{"title": "% tích cực theo thể loại (tháng gần nhất trong khoảng)", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "data": {
  "url": {
   "index": "batch_segment_stats",
   "body": {
    "size": 0,
    "query": {
     "bool": {
      "must": [
       "%dashboard_context-must_clause%",
       {
        "term": {
         "dimension": "genre"
        }
       },
       {
        "range": {
         "month": {
          "%timefilter%": true
         }
        }
       }
      ],
      "filter": [
       "%dashboard_context-filter_clause%"
      ],
      "must_not": [
       "%dashboard_context-must_not_clause%"
      ]
     }
    },
    "aggs": {
     "x": {
      "terms": {
       "field": "segment",
       "size": 20
      },
      "aggs": {
       "pos": {
        "sum": {
         "field": "positive_reviews"
        }
       },
       "tot": {
        "sum": {
         "field": "total_reviews"
        }
       }
      }
     }
    }
   }
  },
  "format": {
   "property": "aggregations.x.buckets"
  }
 },
 "mark": "bar",
 "encoding": {
  "y": {
   "field": "key",
   "type": "nominal",
   "sort": "-x",
   "title": "Thể loại"
  },
  "x": {
   "field": "positive_pct",
   "type": "quantitative",
   "title": "% tích cực"
  }
 },
 "config": {
  "axis": {
   "labelLimit": 160
  }
 },
 "transform": [
  {
   "calculate": "datum.pos.value * 100 / max(datum.tot.value, 1)",
   "as": "positive_pct"
  }
 ]
}"}}

